#include <iostream>
#include <vector>
#include <cmath>
#include <cassert>
#include <cstring>

using namespace std;

const unsigned long long MOD = 1000000007ULL;

struct Matrix {
    int size;
    unsigned long long data[33][33];

    Matrix(int n = 0, unsigned long long val = 0) : size(n) {
        memset(data, 0, sizeof(data));
        for (int i = 0; i < n; ++i) {
            data[i][i] = val;
        }
    }

    Matrix operator*(const Matrix& other) const {
        assert(size == other.size);
        Matrix result(size);
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                for (int k = 0; k < size; ++k) {
                    result.data[i][k] = (result.data[i][k] + data[i][j] * other.data[j][k]) % MOD;
                }
            }
        }
        return result;
    }

    Matrix& operator*=(const Matrix& other) {
        *this = *this * other;
        return *this;
    }

    Matrix power(int exp) const {
        Matrix res(size, 1);
        Matrix base = *this;
        int e = exp;
        while (e > 0) {
            if (e & 1) res *= base;
            base *= base;
            e >>= 1;
        }
        return res;
    }
};

int main() {
    unsigned long long n;
    int k;
    cin >> n >> k;
    if (n <= k) {
        cout << (1ULL << n) % MOD << "\n";
        return 0;
    }

    int logN = int(log(n + 0.0) / log(k + 0.0)) + 2;

    Matrix shift(k + 1, 1);
    for (int j = 0; j < k; ++j) {
        shift.data[j][j] = 0;
        shift.data[(j + 1) % k][j] = 1;
    }

    vector<Matrix> blocks(logN);
    blocks[0] = Matrix(k + 1, 1);
    for (int i = 1; i <= k; ++i) {
        blocks[0].data[0][i] = 1;
    }

    for (int i = 1; i < logN; ++i) {
        blocks[i] = (blocks[i - 1] * shift).power(k);
    }

    int idx = 0;
    unsigned long long len = 1;
    while (n / len >= k) {
        ++idx;
        len *= k;
    }

    Matrix m(k + 1, 1);
    unsigned long long rem = n;
    unsigned long long current_length = len;
    int i = idx;

    while (rem > 0) {
        if (current_length <= rem) {
            int x = int(rem / current_length);
            m *= (blocks[i] * shift).power(x);
            rem -= current_length * x;
        }
        --i;
        current_length /= k;
    }

    unsigned long long ans = 0;
    for (int i = 0; i <= k; ++i) {
        ans = (ans + m.data[i][k]) % MOD;
    }
    cout << ans << "\n";

    return 0;
}
